class MyQueue {
  private main: number[] = []; // top of the stack = front of the queue
  private tmp: number[] = [];

  push(x: number): void {
    while (this.main.length) this.tmp.push(this.main.pop()!);
    this.main.push(x);
    while (this.tmp.length) this.main.push(this.tmp.pop()!);
  }

  pop(): number {
    return this.main.pop()!;
  }

  peek(): number {
    return this.main[this.main.length - 1];
  }

  empty(): boolean {
    return this.main.length === 0;
  }
}

