class MyQueue:
    def __init__(self):
        self.main = []  # top of the stack = front of the queue
        self.tmp = []

    def push(self, x: int) -> None:
        while self.main:
            self.tmp.append(self.main.pop())
        self.main.append(x)
        while self.tmp:
            self.main.append(self.tmp.pop())

    def pop(self) -> int:
        return self.main.pop()

    def peek(self) -> int:
        return self.main[-1]

    def empty(self) -> bool:
        return not self.main

